{
  "skill_name": "geo-local-optimizer",
  "evals": [
    {
      "id": 1,
      "prompt": "I run a small chain of three specialty coffee shops in one city. I want ChatGPT and Perplexity to be more likely to recommend us when people ask for 'good cafes to work from' near our neighborhoods. Help me design a local GEO plan across our website, store pages, Google Maps / Apple Maps, and review profiles, using the workflow of this skill.",
      "expected_output": "A structured markdown local GEO plan following the skill's output format, including Local Business Brief, Local Presence Snapshot, Local Entity & Page Plan, Local Page Structures, Local Structured Data Package, Local Reputation & Q&A Plan, Local AI & Crawler Signaling Plan, and Measurement & Iteration sections.",
      "files": []
    },
    {
      "id": 2,
      "prompt": "We are a neighborhood dental clinic that gets most patients from local search. Please analyze our situation (we have one main clinic and a second smaller location), then propose how to structure our website location pages, local FAQ, map listings, and schema so that AI assistants and search engines clearly understand who we serve, where we are, and when we are open.",
      "expected_output": "A detailed, step-by-step local GEO optimization plan formatted with the skill's headings, with special attention to Local Entity & Page Plan, Local Page Structures, and Local Structured Data Package, plus concrete recommendations for map listings and reviews.",
      "files": []
    },
    {
      "id": 3,
      "prompt": "I am a personal trainer who serves two specific districts in my city and also offers at-home training. Create a complete AI-local optimization workflow for me: which pages to create on my site (location and service-area pages), how to describe my services and target clients, what structured data to use, what to change in my map listings, and how to systematically collect reviews and Q&A for local discovery.",
      "expected_output": "An end-to-end local GEO optimization plan using the skill's recommended structure, clearly tying together website structure, service-area coverage, structured data, reviews, Q&A, and AI & crawler signaling.",
      "files": []
    }
  ]
}
